import { readFile } from "node:fs/promises";
import { createForks } from "@tigrisdata/agent-kit";
import { put } from "@tigrisdata/storage";

async function main() {
  const rawTrialId = (await readFile('/logs/artifacts/trial_id', 'utf8')).trim();
  const trialId = rawTrialId.toLowerCase().replace(/[^a-z0-9.-]/g, '-');

  const sourceBucket = `harbor-source-${trialId}`;
  const forkPrefix = `harbor-fork-${trialId}`;

  const response = await createForks(sourceBucket, 3, { prefix: forkPrefix });

  if (response.error) {
    console.error("Error creating forks:", response.error);
    process.exit(1);
  }

  const forkSet = response.data;
  if (!forkSet || !forkSet.forks) {
    console.error("No forks returned");
    process.exit(1);
  }

  const promises = forkSet.forks.map((fork, i) => {
    return put("worker/output.txt", `worker-${i}`, { config: { bucket: fork.bucket } });
  });

  await Promise.all(promises);

  for (const fork of forkSet.forks) {
    console.log(fork.bucket);
  }
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});

